mapper.select:
SELECT DISTINCT ON (sf.id)
,sc.id as sc_id, sc.video_id as sc_video_id, sc.sub_id as sc_sub_id, v.id as v_id, v.video_name as v_video_name, v.video_name_index as v_video_name_index, v.file_id as v_file_id, v2.video_source as video_source, s.id as s_id, s.name as s_name, s.name_index as s_name_index, s.description as s_description, s.sub_img_id as s_sub_img_id
, COALESCE((select count(id) from gc_user_save_content where folder_id=sf.id and master_id=#{masterId}),0) as videoNum, (select f.id from gc_user_save_content sc left join sys_file f on f.id = sc.file_id where sc.folder_id=sf.id and sc.master_id=#{masterId} order by sc.create_time asc limit 1) as firstVideoFileId from gc_user_save_folder sf left join gc_user_save_content sc on sc.folder_id = sf.id left join gc_video v on v.id = sc.video_id left join gc_subject s on s.id= sc.sub_id left join sys_file fs on s.sub_img_id=fs.id left join sys_file f on v.file_id=f.id left join gc_user u on u.id = sf.user_id left join gc_user_info info on info.id = u.info_id left join sys_file uf on info.avatar_file_id = uf.id left join gc_subject sv on sv.id= v.sub_id left join gc_video v2 on v2.file_id = f.id where 1=1
AND sf.user_id !=#{userId}
and (sf.if_private != 1) and sf.master_id=#{masterId}
AND sf.id in
#{folderId}
AND sf.id not in
#{myFolderId}
order by sf.id DESC, sf.create_time DESC, sc.create_time DESC

SELECT DISTINCT ON (sc.file_id)
,sc.id as sc_id, sc.video_id as sc_video_id, sc.sub_id as sc_sub_id, sc.file_id, sc.file_id as sc_file_id, v.id as v_id, v.video_name as v_video_name, v.video_name_index as v_video_name_index, v.file_id as v_file_id, s.id as s_id, s.name as s_name, s.name_index as s_name_index, s.description as s_description, s.sub_img_id as s_sub_img_id
, COALESCE((select count(id) from gc_user_save_content where folder_id=sf.id and master_id=#{masterId}),0) as videoNum, (select f.id from gc_user_save_content sc left join sys_file f on f.id = sc.file_id where sc.folder_id=sf.id and sc.master_id=#{masterId} order by sc.create_time asc limit 1) as firstVideoFileId from gc_user_save_folder sf left join gc_user_save_content sc on sc.folder_id = sf.id
AND sc.user_id=#{userId}
left join gc_video v on v.id = sc.video_id left join gc_subject s on s.id= sc.sub_id left join sys_file fs on s.sub_img_id=fs.id left join sys_file f on v.file_id=f.id
left join gc_subject sv on sv.id= v.sub_id
where 1=1
AND sf.user_id=#{userId}
and sf.master_id=#{masterId}
AND sf.id in
#{folderId}
AND sf.id not in
#{myFolderId}
order by sc.file_id, sf.create_time asc,sc.create_time asc

select count(1) from gc_user_save_folder
where 1=1

and id in

	#{folderId}


and user_id = #{userId}

SELECT sf.name,c.file_id as sc_file_id,GREATEST(sf.update_time, c.update_time) AS update_time, c.video_id as sc_video_id from gc_user_save_folder sf LEFT JOIN gc_user_save_content c on sf.id=c.folder_id WHERE sf.id=#{folderId}
and c.file_id=#{fileId}
ORDER BY ABS(EXTRACT(EPOCH FROM (sf.update_time - c.update_time))) desc LIMIT 1
